# Streamlit runs on :8501 and FastAPI on :8000 — different origins. Without CORS
# every browser call from the frontend would be silently blocked. Extra origins
# (e.g. a deployed Streamlit URL) can be added via the ALLOWED_ORIGINS env var
# as a comma-separated list.
_default_origins = ["http://localhost:8501", "http://127.0.0.1:8501"]
_extra_origins = [
    o.strip() for o in os.getenv("ALLOWED_ORIGINS", "").split(",") if o.strip()
]
# [SECURITY HARDENING] M-4: restrict CORS to the exact origins, methods, and
# headers the app uses instead of "*". Browser origin policy is the HTTP-header
# mechanism from Meeting 3A; we keep the gate as narrow as the app needs.
app.add_middleware(
    CORSMiddleware,
    allow_origins=_default_origins + _extra_origins,
    allow_credentials=True,
    allow_methods=["GET", "POST", "PATCH", "DELETE", "OPTIONS"],  # [FEATURE] PATCH/DELETE for edit/delete
    allow_headers=["Authorization", "Content-Type"],
)

# Directory where uploaded files are stored on disk.
