@app.post("/auth/register", response_model=UserOut, status_code=status.HTTP_201_CREATED)
def register(user: UserCreate) -> UserOut:
    """Register a new user with a bcrypt-hashed password."""
    if database.get_user_by_username(user.username) is not None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Username already taken",
        )
    try:
        database.create_user(user.username, auth.hash_password(user.password))
    except sqlite3.IntegrityError:
        # Race condition guard: another request created the same name first.
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Username already taken",
        )
    row = database.get_user_by_username(user.username)
    return UserOut(id=row["id"], username=row["username"], created_at=row["created_at"])


@app.get("/auth/me")
def whoami(username: str = Depends(auth.get_current_user)) -> dict:
    """Return the username behind a valid Bearer token, else 401.

    [BUGFIX-SESSION] The frontend persists its JWT in the URL query string so a
    browser refresh (which starts a brand-new Streamlit session) can restore the
    login. On startup it calls this endpoint to validate that stored token and
    learn which user it represents — exactly the stateless "prove who you are"
    check (Meeting 4A), reusing the same get_current_user guard as every other
    protected route. A missing/expired/forged token yields 401 and the frontend
    simply falls back to the login screen.
    """
    return {"username": username}


@app.post("/auth/login", response_model=Token)
def login(user: UserCreate) -> Token:
    """Validate credentials and return a JWT access token."""
    row = database.get_user_by_username(user.username)
    # Same generic error for "no such user" and "wrong password" so we never
    # reveal which field was wrong.
    if row is None or not auth.verify_password(user.password, row["hashed_password"]):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Incorrect username or password",
        )
    return Token(access_token=auth.create_access_token(row["username"]))


# --------------------------------------------------------------------------- #
# Message routes
# --------------------------------------------------------------------------- #
# [TZ] Messages are stored with SQLite's datetime('now') default, which is UTC.
# Convert that UTC text to current Israel local time (Asia/Jerusalem, DST-aware)
# for display only — the stored value stays UTC and the format is unchanged.
_ISRAEL_TZ = ZoneInfo("Asia/Jerusalem")


def _to_israel_time(ts: Optional[str]) -> Optional[str]:
    """Render a stored UTC ``YYYY-MM-DD HH:MM:SS`` timestamp in Israel local time."""
    if not ts:
        return ts
    try:
        dt = datetime.strptime(ts, "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
        return dt.astimezone(_ISRAEL_TZ).strftime("%Y-%m-%d %H:%M:%S")
    except (ValueError, TypeError):
        return ts  # unknown format — leave it as-is rather than crash


def _row_to_message(row: sqlite3.Row, seen: bool = False) -> MessageOut:
    """Convert a SQLite row into a MessageOut model.

    ``seen`` is only meaningful for direct messages (read receipts); it is left
    False for public/group messages.
    """
    keys = row.keys()  # tolerate rows that predate the edited/is_deleted columns
    return MessageOut(
        id=row["id"],
        sender_username=row["sender_username"],
        content=row["content"],
        timestamp=_to_israel_time(row["timestamp"]),  # [TZ] UTC -> Asia/Jerusalem
        group_id=row["group_id"],
        recipient_username=row["recipient_username"],
        file_name=row["file_name"],
        file_type=row["file_type"],
        edited=bool(row["edited"]) if "edited" in keys else False,  # [FEATURE]
        is_deleted=bool(row["is_deleted"]) if "is_deleted" in keys else False,  # [FEATURE]
        seen=seen,  # [FEATURE]
    )


@app.get("/messages", response_model=list[MessageOut])
def list_messages(
    group_id: Optional[int] = None,
    username: str = Depends(auth.get_current_user),
) -> list[MessageOut]:
    """Return all messages (oldest first) for the global chat or a group."""
    _require_group_access(group_id, username)  # [SECURITY HARDENING] H-2
    return [_row_to_message(r) for r in database.get_messages(group_id)]


@app.post("/messages", response_model=MessageOut, status_code=status.HTTP_201_CREATED)
async def send_message(
    message: MessageCreate,
    username: str = Depends(auth.get_current_user),
) -> MessageOut:
    """Persist a new message (public, group, or direct) and broadcast it.

    The realtime push is scoped to exactly who is allowed to see the message:
    everyone (public), the group's members, or the two DM participants.
    """
    # A message belongs to one channel only.
    if message.group_id is not None and message.recipient_username is not None:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="A message cannot be both a group and a direct message",
        )

    recipients: Optional[set[str]] = None  # None = everyone (public)

    if message.recipient_username is not None:
        # --- Direct (1-to-1) message ---
        if message.recipient_username == username:
            raise HTTPException(status_code=400, detail="You cannot DM yourself")
        if not database.user_exists(message.recipient_username):
            raise HTTPException(status_code=404, detail="Recipient not found")
        recipients = {username, message.recipient_username}
    else:
        # --- Public or group message ---
        _require_group_access(message.group_id, username)  # [SECURITY HARDENING] H-2
        if message.group_id is not None:
            recipients = database.get_group_member_usernames(message.group_id)

    row = database.insert_message(
        username,
        message.content,
        group_id=message.group_id,
        recipient_username=message.recipient_username,
    )
    out = _row_to_message(row)
    await manager.broadcast(out.model_dump(), recipients=recipients)
    return out


@app.get("/users", response_model=list[str])
def list_users(username: str = Depends(auth.get_current_user)) -> list[str]:
    """List every registered username except the caller (to start a DM with)."""
    return database.get_all_usernames(exclude=username)


@app.get("/notifications")
def notifications(username: str = Depends(auth.get_current_user)) -> dict:
    """Report the latest message addressed to the caller (for new-message alerts).

    The frontend polls this regardless of which conversation is open, so a new
    direct or group message can raise a notification even when that window is
    closed. Returns the latest incoming message id, who sent it, and where.
    """
    row = database.get_latest_incoming(username)
    if row is None:
        return {"latest_id": 0, "sender": None, "kind": None, "group_id": None}
    kind = "dm" if row["recipient_username"] else ("group" if row["group_id"] else "public")
    return {
        "latest_id": row["id"],
        "sender": row["sender_username"],
        "kind": kind,
        "group_id": row["group_id"],
    }


@app.get("/messages/direct", response_model=list[MessageOut])
def direct_messages(
    with_user: str,
    username: str = Depends(auth.get_current_user),
) -> list[MessageOut]:
    """Return the 1-to-1 conversation between the caller and ``with_user``.

    Authorization is inherent: the query only returns messages whose two
    participants are the caller and ``with_user``.
    """
    if with_user == username:
        return []
    if not database.user_exists(with_user):
        raise HTTPException(status_code=404, detail="User not found")
    # [FEATURE] Read receipts: a message *I* sent is "seen" once the peer's
    # last_read_id has reached it. peer_read is how far ``with_user`` has read.
    peer_read = database.get_dm_last_read(with_user, username)
    out: list[MessageOut] = []
    for r in database.get_direct_messages(username, with_user):
        seen = r["sender_username"] == username and r["id"] <= peer_read
        out.append(_row_to_message(r, seen=seen))
    return out


@app.get("/messages/search", response_model=list[MessageOut])
def search(
    q: str,
    group_id: Optional[int] = None,
    username: str = Depends(auth.get_current_user),
) -> list[MessageOut]:
    """Free-text search over message content (parameterized LIKE query)."""
    _require_group_access(group_id, username)  # [SECURITY HARDENING] H-2
    return [_row_to_message(r) for r in database.search_messages(q, group_id)]


@app.get("/messages/search/all", response_model=list[MessageOut])
def search_all(
    q: str,
    username: str = Depends(auth.get_current_user),
) -> list[MessageOut]:
    """[FEATURE] GLOBAL SEARCH across the caller's public/group/DM messages.

    Substring + case-insensitive (parameterized LIKE). Each result carries its
    channel (group_id / recipient_username) so the UI can show where it belongs
    and jump there. Authorization is inherent: the query only returns the public
    chat, the caller's groups, and the caller's direct messages.
    """
    return [_row_to_message(r) for r in database.search_all_for_user(q, username)]


# --------------------------------------------------------------------------- #
# File / image sharing
# --------------------------------------------------------------------------- #
@app.post("/messages/upload", response_model=MessageOut, status_code=status.HTTP_201_CREATED)
async def upload_file(
    file: UploadFile = File(...),
    content: str = Form(""),
    group_id: Optional[int] = Form(None),
    recipient_username: Optional[str] = Form(None),
    username: str = Depends(auth.get_current_user),
) -> MessageOut:
    """Upload a file/image and attach it to a new (public, group, or DM) message."""
    # Authorize the destination channel before accepting the upload.
    if group_id is not None and recipient_username is not None:
        raise HTTPException(status_code=400, detail="Pick a group or a recipient, not both")
    if recipient_username is not None:
        if recipient_username == username:
            raise HTTPException(status_code=400, detail="You cannot DM yourself")
        if not database.user_exists(recipient_username):
            raise HTTPException(status_code=404, detail="Recipient not found")
        recipients: Optional[set[str]] = {username, recipient_username}
    else:
        _require_group_access(group_id, username)  # [SECURITY HARDENING] H-2
        recipients = (
            database.get_group_member_usernames(group_id)
            if group_id is not None
            else None
        )

    # [SECURITY HARDENING] M-1: validate type, extension, and size before saving.
    ext = os.path.splitext(file.filename or "")[1].lower()
    if file.content_type not in ALLOWED_UPLOAD_TYPES or ext not in ALLOWED_UPLOAD_EXTS:
        raise HTTPException(
            status_code=status.HTTP_415_UNSUPPORTED_MEDIA_TYPE,
            detail="File type not allowed",
        )
    data = await file.read(MAX_UPLOAD_BYTES + 1)
    if len(data) == 0:
        raise HTTPException(status_code=422, detail="Empty file")
    if len(data) > MAX_UPLOAD_BYTES:
        raise HTTPException(
            status_code=status.HTTP_413_REQUEST_ENTITY_TOO_LARGE,
            detail="File exceeds the 5 MB limit",
        )

    # Store under a random UUID name (never the user's filename), keeping only
    # the validated extension — this prevents path traversal and overwrites.
    stored_name = f"{uuid.uuid4().hex}{ext}"
    stored_path = os.path.join(UPLOAD_DIR, stored_name)
    with open(stored_path, "wb") as out_file:
        out_file.write(data)

    # Keep a sanitised copy of the original name for display only.
    safe_display_name = os.path.basename(file.filename or stored_name)
    caption = content.strip() or f"📎 {safe_display_name}"
    row = database.insert_message(
        sender_username=username,
        content=caption,
        group_id=group_id,
        recipient_username=recipient_username,
        file_name=safe_display_name,
        file_path=stored_name,
        file_type=file.content_type,
    )
    out = _row_to_message(row)
    await manager.broadcast(out.model_dump(), recipients=recipients)
    return out


@app.get("/files/{message_id}")
def download_file(
    message_id: int,
    username: str = Depends(auth.get_current_user),
) -> FileResponse:
    """Download the file attached to a message."""
    row = database.get_message_file(message_id)
    if row is None or not row["file_path"]:
        raise HTTPException(status_code=404, detail="No file for this message")
    # [SECURITY HARDENING] M-2: a group file is only downloadable by members, and
    # a direct-message file only by its two participants.
    _require_message_access(
        row["group_id"], row["recipient_username"], row["sender_username"], username
    )
    path = os.path.join(UPLOAD_DIR, row["file_path"])
    if not os.path.exists(path):
        raise HTTPException(status_code=404, detail="File missing on server")
    return FileResponse(
        path,
        media_type=row["file_type"] or "application/octet-stream",
        filename=row["file_name"] or row["file_path"],
    )


# --------------------------------------------------------------------------- #
# [FEATURE] Edit / delete own messages
# --------------------------------------------------------------------------- #
def _recipients_for_message(row: sqlite3.Row) -> Optional[set[str]]:
    """Compute the broadcast recipient set for an existing message row."""
    if row["recipient_username"] is not None:
        return {row["sender_username"], row["recipient_username"]}
    if row["group_id"] is not None:
        return database.get_group_member_usernames(row["group_id"])
    return None  # public


@app.patch("/messages/{message_id}", response_model=MessageOut)
async def edit_message(
    message_id: int,
    edit: MessageEdit,
    username: str = Depends(auth.get_current_user),
) -> MessageOut:
    """Edit one of the caller's own messages. 403 if not the sender."""
    row = database.get_message_owner(message_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Message not found")
    if row["sender_username"] != username:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="You can only edit your own messages",
        )
    updated = database.update_message(message_id, edit.content)
    out = _row_to_message(updated)
    await manager.broadcast(out.model_dump(), recipients=_recipients_for_message(row))
    return out


@app.delete("/messages/{message_id}", response_model=MessageOut)
async def delete_message(
    message_id: int,
    username: str = Depends(auth.get_current_user),
) -> MessageOut:
    """Delete one of the caller's own messages. 403 if not the sender."""
    row = database.get_message_owner(message_id)
    if row is None:
        raise HTTPException(status_code=404, detail="Message not found")
    if row["sender_username"] != username:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="You can only delete your own messages",
        )
    deleted = database.soft_delete_message(message_id)
    out = _row_to_message(deleted)
    await manager.broadcast(out.model_dump(), recipients=_recipients_for_message(row))
    return out


# --------------------------------------------------------------------------- #
# [FEATURE] Read receipts (DMs only)
# --------------------------------------------------------------------------- #
@app.post("/messages/mark-read", status_code=status.HTTP_200_OK)
def mark_read(
    peer: str,
    username: str = Depends(auth.get_current_user),
) -> dict:
    """Mark the DM conversation with ``peer`` as read up to its newest message."""
    if not database.user_exists(peer):
        raise HTTPException(status_code=404, detail="User not found")
    last_read = database.mark_dm_read(username, peer)
    return {"peer": peer, "last_read_id": last_read}


# --------------------------------------------------------------------------- #
# [FEATURE] Typing indicator (lightweight, in-memory, best-effort)
# --------------------------------------------------------------------------- #
# Maps a conversation key -> {username: last_typed_epoch_seconds}. Purely
# in-memory: it is volatile, never persisted, and harmless if lost — so it adds
# no external dependency and degrades gracefully (a restart just clears it).
_TYPING: dict[str, dict[str, float]] = {}
_TYPING_TTL = 4.0  # seconds a "typing…" signal stays fresh


def _typing_key(group_id: Optional[int], peer: str, me: str) -> str:
    """Stable conversation key. DMs use the sorted user pair so both sides match."""
    if peer:
        a, b = sorted([me, peer])
        return f"dm:{a}:{b}"
    if group_id is not None:
        return f"group:{group_id}"
    return "public"


@app.post("/typing", status_code=status.HTTP_200_OK)
def typing(
    ping: TypingPing,
    username: str = Depends(auth.get_current_user),
) -> dict:
    """Record that ``username`` is typing in a conversation (group/public/DM)."""
    peer = ping.peer or ""
    if peer:
        if peer == username or not database.user_exists(peer):
            raise HTTPException(status_code=404, detail="User not found")
    elif ping.group_id is not None:
        _require_group_access(ping.group_id, username)  # [SECURITY HARDENING] H-2
    key = _typing_key(ping.group_id, peer, username)
    _TYPING.setdefault(key, {})[username] = time.time()
    return {"ok": True}


@app.get("/typing")
def typing_status(
    group_id: Optional[int] = None,
    peer: str = "",
    username: str = Depends(auth.get_current_user),
) -> dict:
    """Return who (besides the caller) has typed in the last few seconds."""
    if peer:
        if peer == username or not database.user_exists(peer):
            return {"typing": []}
    elif group_id is not None:
        _require_group_access(group_id, username)  # [SECURITY HARDENING] H-2
    key = _typing_key(group_id, peer, username)
    now = time.time()
    fresh = _TYPING.get(key, {})
    active = [
        u for u, ts in fresh.items() if u != username and now - ts <= _TYPING_TTL
    ]
    return {"typing": sorted(active)}


# --------------------------------------------------------------------------- #
# [FEATURE] OAuth/SSO stub config (default OFF)
# --------------------------------------------------------------------------- #
@app.get("/auth/config")
def auth_config() -> dict:
    """Advertise whether the (stub) SSO button should be shown. Default: off."""
    return {"oauth_enabled": _oauth_enabled()}


# --------------------------------------------------------------------------- #
# Group chat routes
# --------------------------------------------------------------------------- #
@app.get("/groups", response_model=list[GroupOut])
def list_groups(username: str = Depends(auth.get_current_user)) -> list[GroupOut]:
    """List only the groups the caller is a member of.

    [FEATURE] PRIVATE GROUPS: a group is invite-only, so a user only ever sees
    groups they were added to — never every group on the server.
    """
    return [
        GroupOut(id=r["id"], name=r["name"], created_at=r["created_at"])
        for r in database.get_groups_for_user(username)
    ]


@app.post("/groups", response_model=GroupOut, status_code=status.HTTP_201_CREATED)
def create_group(
    group: GroupCreate,
    username: str = Depends(auth.get_current_user),
) -> GroupOut:
    """Create a new private group chat.

    [FEATURE] PRIVATE GROUPS: the creator joins automatically and the invited
    ``members`` are added so only they can see and post in the group. Unknown
    usernames are silently dropped (defence in depth — they would also violate the
    group_members foreign key); the creator is never duplicated.
    """
    members = [
        m for m in group.members if m != username and database.user_exists(m)
    ]
    try:
        row = database.create_group(group.name, username, members)
    except sqlite3.IntegrityError:
        raise HTTPException(status_code=400, detail="Group name already exists")
    return GroupOut(id=row["id"], name=row["name"], created_at=row["created_at"])


@app.post("/groups/{group_id}/join", status_code=status.HTTP_200_OK)
def join_group(
    group_id: int,
    username: str = Depends(auth.get_current_user),
) -> dict:
    """Join an existing group chat."""
    if not database.join_group(group_id, username):
        raise HTTPException(status_code=404, detail="Group not found")
    return {"detail": f"{username} joined group {group_id}"}


# --------------------------------------------------------------------------- #
# WebSocket route
# --------------------------------------------------------------------------- #
@app.websocket("/ws")
async def websocket_endpoint(websocket: WebSocket, token: str = "") -> None:
    """Authenticated real-time channel.

    [SECURITY HARDENING] H-1: the client must supply a valid JWT as the ``token``
    query parameter (``ws://host/ws?token=<jwt>``). The username is taken from
    the verified token — never from client-supplied text — so a connection
    cannot be opened anonymously or impersonate another user. Invalid tokens are
    rejected with WS close code 1008 (policy violation).
    """
    username = auth.decode_token(token)
    if username is None:
        await websocket.close(code=status.WS_1008_POLICY_VIOLATION)
        return

    await manager.connect(websocket, username)
    try:
        await websocket.send_json({"system": f"{username} connected"})
        while True:
            # We don't require the client to send anything; this await simply
            # keeps the connection open and detects disconnects.
            await websocket.receive_text()
    except WebSocketDisconnect:
        manager.disconnect(websocket)


# [SECURITY HARDENING] L-2: a catch-all handler so unexpected errors return a
# generic 500 (the course's "5xx = server's fault", Meeting 3A) without leaking
# stack traces or internal details to the client.
@app.exception_handler(Exception)
async def unhandled_exception_handler(request: Request, exc: Exception) -> JSONResponse:
    return JSONResponse(
        status_code=status.HTTP_500_INTERNAL_SERVER_ERROR,
        content={"detail": "Internal server error"},
    )


@app.get("/")
def root() -> dict:
    """Tiny health-check endpoint."""
    return {"service": "SimpleChat API", "status": "ok"}
